//! Cargo-driven `tracert.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is tracert-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wmainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wmainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wmainCRTStartup"),
        o => panic!("tracert-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:conutils", "import:ws2_32", "import:iphlpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "engine:pseh", "engine:chkstk", "engine:conutils_rust"],
        "x86_64" => &["body", "engine:conutils", "import:ws2_32", "import:iphlpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "engine:pseh", "engine:conutils_rust"],
        "aarch64" => &["body", "engine:conutils", "import:ws2_32", "import:iphlpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "engine:pseh", "engine:chkstk", "engine:conutils_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/applications/network/tracert",
        "base/applications/network/tracert",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/conutils",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("tracert-rust")
        .c_from_compile_db("tracert_shims", &["base/applications/network/tracert/rust_cohab_stub.cpp"])
        .rc("base/applications/network/tracert/tracert.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
